<template><section class="section container"><div class="eyebrow">Struktur konten</div><h1>Kategori</h1><form class="toolbar" @submit.prevent="save"><input v-model="name" placeholder="Nama kategori baru" required><button class="btn btn-primary">Tambah kategori</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Nama</th><th>Slug</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in store.list" :key="item.id"><td>{{ item.nama }}</td><td>{{ item.slug }}</td><td><button class="btn btn-danger" @click="remove(item.id)">Hapus</button></td></tr></tbody></table></div></section></template><script setup>definePageMeta({middleware:'admin'});const store=useKategoriStore();const name=ref('');await store.fetchAll();async function save(){await store.create({nama:name.value});name.value=''}async function remove(id){if(confirm('Hapus kategori ini?'))await store.remove(id)}</script>
